function mix(a,b,t){return a+(b-a)*t;}
function mix3(a,b,t){return[mix(a[0],b[0],t),mix(a[1],b[1],t),mix(a[2],b[2],t)];}
function bez(a,b,c,t){return mix3(mix3(a,b,t),mix3(b,c,t),t);}
